import { CognitiveLevel, QuestionRecord, StationRecord } from '../types/game';

type CompactQ = [
  idSuffix: string,
  level: CognitiveLevel,
  skill: string,
  context: string,
  prompt: string,
  optA: string,
  optB: string,
  optC: string,
  optD: string,
  correct: 'A' | 'B' | 'C' | 'D',
  explanation: string,
  unit?: string | null,
  approved?: boolean
];

const OPTION_LETTERS: ('A' | 'B' | 'C' | 'D')[] = ['A', 'B', 'C', 'D'];

function hashQuestionKey(str: string): number {
  let h = 2166136261;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return Math.abs(h);
}

/**
 * Permutes a QuestionRecord's 4 options so the correct answer is placed at `targetCorrectLetter`
 * (or a randomly chosen letter if omitted) and the 3 distractors are shuffled into the remaining slots.
 */
export function shuffleQuestionOptions(
  q: QuestionRecord,
  targetCorrectLetter?: 'A' | 'B' | 'C' | 'D'
): QuestionRecord {
  const currentCorrectOpt =
    q.options.find((o) => o.id === q.correct_option_id) || q.options[0];
  const distractors = q.options
    .filter((o) => o.id !== currentCorrectOpt.id)
    .map((o) => o.text);

  // Fisher-Yates shuffle on distractors
  for (let i = distractors.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [distractors[i], distractors[j]] = [distractors[j], distractors[i]];
  }

  const chosenCorrectLetter: 'A' | 'B' | 'C' | 'D' =
    targetCorrectLetter ||
    OPTION_LETTERS[Math.floor(Math.random() * OPTION_LETTERS.length)];

  let dIdx = 0;
  const newOptions = OPTION_LETTERS.map((letter) => {
    if (letter === chosenCorrectLetter) {
      return { id: letter, text: currentCorrectOpt.text };
    }
    return { id: letter, text: distractors[dIdx++] ?? '' };
  });

  const updatedSolutionSteps = q.solution_steps
    ? [
        ...q.solution_steps.slice(0, -1),
        `Kết luận đáp án đúng: ${chosenCorrectLetter} (${currentCorrectOpt.text}).`,
      ]
    : undefined;

  return {
    ...q,
    options: newOptions,
    correct_option_id: chosenCorrectLetter,
    accepted_answers: [chosenCorrectLetter, currentCorrectOpt.text],
    solution_steps: updatedSolutionSteps,
  };
}

function expandQuestions(
  quantityId: string,
  stationPrefix: string,
  lessonRefs: string[],
  items: CompactQ[]
): QuestionRecord[] {
  const stationHash = hashQuestionKey(stationPrefix);
  return items.map(
    (
      [
        suffix,
        level,
        skill,
        context,
        prompt,
        a,
        b,
        c,
        d,
        correct,
        explanation,
        unit = null,
        approved = true,
      ],
      itemIdx
    ) => {
      const optMap: Record<'A' | 'B' | 'C' | 'D', string> = {
        A: a,
        B: b,
        C: c,
        D: d,
      };
      const correctText = optMap[correct];
      const rawDistractors = OPTION_LETTERS.filter((k) => k !== correct).map(
        (k) => optMap[k]
      );

      // Deterministic balanced target slot (A, B, C, D) across items in the bank
      const qHash = hashQuestionKey(`${stationPrefix}_${suffix}_${prompt}`);
      const targetSlotIndex = (itemIdx + (stationHash % 4) + (qHash % 3)) % 4;
      const finalCorrectLetter = OPTION_LETTERS[targetSlotIndex];

      // Deterministically permute distractors so bank order is also varied
      const dShift = qHash % 3;
      const rotatedDistractors = [
        ...rawDistractors.slice(dShift),
        ...rawDistractors.slice(0, dShift),
      ];

      let distCursor = 0;
      const finalOptions = OPTION_LETTERS.map((letter) => {
        if (letter === finalCorrectLetter) {
          return { id: letter, text: correctText };
        }
        return { id: letter, text: rotatedDistractors[distCursor++] };
      });

      return {
        question_id: `${stationPrefix}_${suffix}`,
        station_id: stationPrefix,
        target_quantity_id: quantityId,
        lesson_refs: lessonRefs,
        level,
        skill,
        context,
        prompt,
        options: finalOptions,
        correct_option_id: finalCorrectLetter,
        explanation_vi: explanation,
        expected_unit: unit,
        accepted_answers: [finalCorrectLetter, correctText],
        numeric_tolerance: level === 'apply' ? 0 : null,
        solution_steps:
          level === 'apply'
            ? [
                `Xác định dữ kiện đề bài và đơn vị chuẩn (${unit || 'theo hệ SI'}).`,
                explanation,
                `Kết luận đáp án đúng: ${finalCorrectLetter} (${correctText}).`,
              ]
            : undefined,
        difficulty: level === 'apply' ? 3 : level === 'understand' ? 2 : 1,
        source_status: approved ? 'approved' : 'teacher_review',
        teacher_approved: approved,
      };
    }
  );
}

