/**
 * Selects a deterministic 10-question assessment set for a given station:
 * - Strictly 4 Know + 3 Understand + 3 Apply
 * - Strictly filters ONLY `teacher_approved === true` and `source_status === 'approved'`
 * - On retry (`attemptCount > 0`), prioritizes questions not in `lastQuestionIds`
 *   to satisfy `retry_policy: "new_equivalent_set"` from 02 & 03 specs!
 */
export function selectQuestionsForStationAttempt(
  station: StationRecord,
  allQuestions: QuestionRecord[],
  lastQuestionIds: string[] = [],
  attemptSeed = 0,
  reviewQueueIds: string[] = []
): QuestionRecord[] {
  // Filter only approved questions
  const approvedPool = allQuestions.filter(
    (q) => q.teacher_approved === true && q.source_status === 'approved'
  );

  let candidatePool: QuestionRecord[] = [];

  if (station.station_type === 'checkpoint') {
    // Checkpoints draw from integrative checkpoint questions, never regular station questions
    const cpSpecific = approvedPool.filter((q) => q.station_id === station.station_id);
    const cpAll = approvedPool.filter((q) => q.target_quantity_id === 'PHY_CHECKPOINT_SYNTHESIS');
    // Put specific checkpoint items first, then other checkpoint synthesis items for retry variety
    candidatePool = [...cpSpecific, ...cpAll.filter((q) => q.station_id !== station.station_id)];
  } else {
    // Regular or application stations draw from their target quantity pool
    candidatePool = approvedPool.filter((q) => q.target_quantity_id === station.target_quantity_id);
  }

  const pickByLevel = (level: CognitiveLevel, count: number): QuestionRecord[] => {
    const levelItems = candidatePool.filter((q) => q.level === level);
    // Separate unseen vs reviewQueue vs seen in previous attempt for "new_equivalent_set" retry behavior
    const unseen = levelItems.filter((q) => !lastQuestionIds.includes(q.question_id));
    const inReviewQueue = levelItems.filter(
      (q) => lastQuestionIds.includes(q.question_id) && reviewQueueIds.includes(q.question_id)
    );
    const seenOther = levelItems.filter(
      (q) => lastQuestionIds.includes(q.question_id) && !reviewQueueIds.includes(q.question_id)
    );

    // Rotate deterministically by attemptSeed so retries get fresh equivalent questions first, followed by review_queue items
    const rotate = <T,>(arr: T[], shift: number): T[] => {
      if (arr.length <= 1) return arr;
      const offset = shift % arr.length;
      return [...arr.slice(offset), ...arr.slice(0, offset)];
    };

    const ordered = [
      ...rotate(unseen, attemptSeed),
      ...rotate(inReviewQueue, attemptSeed),
      ...rotate(seenOther, attemptSeed + 1),
    ];
    return ordered.slice(0, count);
  };

  const knowSet = pickByLevel('know', 4);
  const understandSet = pickByLevel('understand', 3);
  const applySet = pickByLevel('apply', 3);

  const rawSelected = [...knowSet, ...understandSet, ...applySet];

  // Build a balanced random deck of 10 correct answer positions (2 of each A,B,C,D + 2 random distinct letters)
  const extraPair = [...OPTION_LETTERS].sort(() => Math.random() - 0.5).slice(0, 2);
  const balancedTargetLetters: ('A' | 'B' | 'C' | 'D')[] = [
    'A',
    'B',
    'C',
    'D',
    'A',
    'B',
    'C',
    'D',
    ...extraPair,
  ];
  // Fisher-Yates shuffle the target letter deck so the sequence of correct letters is completely unpredictable
  for (let i = balancedTargetLetters.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [balancedTargetLetters[i], balancedTargetLetters[j]] = [
      balancedTargetLetters[j],
      balancedTargetLetters[i],
    ];
  }

  return rawSelected.map((q, idx) => {
    const shuffled = shuffleQuestionOptions(
      q,
      balancedTargetLetters[idx % balancedTargetLetters.length]
    );
    return {
      ...shuffled,
      // Tag with station_id for attempt tracking while keeping original question_id
      station_id: station.station_id,
      question_id: q.question_id || `${station.station_id}_Q${idx + 1}`,
    };
  });
}
